%[text] # Prestressed truss-cable beam example using OpenSeesMatlab
%[text] A simply supported beam is strengthened by a vertical prestressed cable.
%[text] The initial cable strain minimizes $\\int\_0^L M^2,dx$; closed-form beam
%[text] solutions provide an independent check. Units are m, N, and Pa.
clear; clc; close all;
exampleFolder = "";
%%
%[text] ## 1. Model and numerical parameters
%[text] Geometry, material properties, and mesh density are collected here so that
%[text] the example can be modified without changing the analysis functions.
L  = 12.0;        % Beam span, m
q  = 30e3;        % Uniform load, N/m

E  = 200e9;       % Beam Young's modulus, Pa
A  = 0.020;       % Beam area, m^2
Iz = 8.0e-4;      % Beam moment of inertia, m^4

Ec = 200e9;       % Cable Young's modulus, Pa
Ac = 2.0e-4;      % Cable area, m^2
hc = 2.0;         % Cable anchor height, m

nEle = 80;        % Number of beam elements
if mod(nEle,2) ~= 0
    error('nEle must be even.');
end

figDir = fullfile(exampleFolder, 'figures');
if ~exist(figDir,'dir'); mkdir(figDir); end
%%
%[text] ## 2. Theoretical reference
%[text] For a simply supported beam under uniform load q and an upward force N at
%[text] midspan, minimizing int\_0^L M^2 dx gives the following closed-form optimum.
%[text] This value is used to check the optimized cable force.
NExact = 5*q*L/8;

% A rough initial-strain estimate
epsGuess = NExact/(Ec*Ac);

fprintf('Theoretical optimum force N = %.3e N\n', NExact); %[output:0146273b]
fprintf('Initial guess for eps0      = %.3e\n\n', epsGuess); %[output:2f9b656b]
%%
%[text] ## 3. Optimize the cable initial strain
%[text] The design variable is eps0, the initial strain assigned to the cable
%[text] material. For each trial value, OpenSeesMatlab rebuilds and analyzes the
%[text] model, and MATLAB evaluates the objective from the recovered bending
%[text] moments.
obj = @(eps0) runModel(eps0, 0.0, L, q, E, A, Iz, Ec, Ac, hc, nEle).J;

eps0Opt = fminbnd(obj, 0.0, 5*epsGuess);

fprintf('Optimized cable initial strain eps0 = %.6e\n\n', eps0Opt); %[output:48ed8262]
%%
%[text] ## 4. Run verification cases
%[text] The three cases separate the effects of an unstressed cable, an explicit
%[text] upward force, and optimized prestress. They are used in the paper figure.
%[text] Case 1: cable exists, but eps0 = 0
case0 = runModel(0.0, 0.0, L, q, E, A, Iz, Ec, Ac, hc, nEle);

% Case 2: cable exists, eps0 = 0, plus direct upward force qL/2
caseF = runModel(0.0, q*L/2, L, q, E, A, Iz, Ec, Ac, hc, nEle);

% Case 3: optimized prestressed cable
caseP = runModel(eps0Opt, 0.0, L, q, E, A, Iz, Ec, Ac, hc, nEle);

%%
%[text] ## 5. Print verification summary
fprintf('Case 1: eps0 = 0\n'); %[output:9210ab35]
fprintf('  Cable force = %.3e N\n', case0.Ncable); %[output:8216c2fd]
fprintf('  Objective J = %.3e\n\n', case0.J); %[output:1f7b5419]

fprintf('Case 2: direct force qL/2\n'); %[output:33ff5118]
fprintf('  Cable force = %.3e N\n', caseF.Ncable); %[output:6100cd4b]
fprintf('  Objective J = %.3e\n', caseF.J); %[output:609185e3]
fprintf('  Reduction   = %.2f %%n\n', 100*(case0.J-caseF.J)/case0.J); %[output:1fec7580]
fprintf('Case 3: optimized prestressed cable\n'); %[output:348d13bc]
fprintf('  Cable force = %.3e N\n', caseP.Ncable); %[output:9e8de464]
fprintf('  Objective J = %.3e\n', caseP.J); %[output:5ce90104]
fprintf('  Reduction   = %.2f %%n\n', 100*(case0.J-caseP.J)/case0.J); %[output:1e7df54d]
%%
%[text] ## 6. Closed-form curves for comparison
%[text] The theoretical curves use the equivalent upward force acting at midspan.
%[text] For the prestressed case, this force is the axial force recovered from the
%[text] cable element.
xTheory = linspace(0,L,1000).';

M0_th = momentTheory(case0.Ncable, xTheory, L, q);
MF_th = momentTheory(q*L/2 + caseF.Ncable, xTheory, L, q);
MP_th = momentTheory(caseP.Ncable, xTheory, L, q);

u0_th = dispTheory(case0.Ncable, xTheory, L, q, E, Iz);
uF_th = dispTheory(q*L/2 + caseF.Ncable, xTheory, L, q, E, Iz);
uP_th = dispTheory(caseP.Ncable, xTheory, L, q, E, Iz);
%%
%[text] ## 7. Plot and save figures
%[text] The figure compares OpenSeesMatlab finite-element results with closed-form
%[text] beam solutions. FE results are plotted as lines; theoretical results are
%[text] shown by markers.
fig = figure('Color','w','Units','centimeters','Position',[3 3 17 15]); %[output:9772e854]
tiledlayout(2,1,'TileSpacing','compact','Padding','compact'); %[output:9772e854]

% -------------------------------------------------------------------------
% Style settings
% -------------------------------------------------------------------------
% Three cases are shown with consistent colors and line styles.
% Lines: finite-element results from OpenSeesMatlab.
% Markers: closed-form beam-theory results.

C = [ ...
    0.00 0.00 0.00;   % Case 1
    0.10 0.35 0.75;   % Case 2
    0.80 0.10 0.10];  % Case 3

LS = {'-','--','-.'};         % line styles for FE
MK = {'o','s','d'};           % markers for theory
LW = [1.6, 1.6, 1.8];         % line widths

% Sample only part of the theory points, otherwise the markers are too dense
idxTh = 1:35:numel(xTheory);
if idxTh(end) ~= numel(xTheory)
    idxTh = [idxTh, numel(xTheory)];
end

% ========================================================================
% (a) Bending moment
% ========================================================================
ax1 = nexttile; %[output:9772e854]
hold(ax1,'on'); box(ax1,'on'); %[output:9772e854]

% FE curves
h1 = plot(ax1, case0.xM, case0.M/1e3, ... %[output:9772e854]
    'LineStyle', LS{1}, 'Color', C(1,:), 'LineWidth', LW(1)); %[output:9772e854]

h2 = plot(ax1, caseF.xM, caseF.M/1e3, ... %[output:9772e854]
    'LineStyle', LS{2}, 'Color', C(2,:), 'LineWidth', LW(2)); %[output:9772e854]

h3 = plot(ax1, caseP.xM, caseP.M/1e3, ... %[output:9772e854]
    'LineStyle', LS{3}, 'Color', C(3,:), 'LineWidth', LW(3)); %[output:9772e854]

% Theory markers
h4 = plot(ax1, xTheory(idxTh), M0_th(idxTh)/1e3, ... %[output:9772e854]
    'LineStyle', 'none', 'Marker', MK{1}, 'Color', C(1,:), ... %[output:9772e854]
    'MarkerSize', 5.0, 'LineWidth', 1.0); %[output:9772e854]

h5 = plot(ax1, xTheory(idxTh), MF_th(idxTh)/1e3, ... %[output:9772e854]
    'LineStyle', 'none', 'Marker', MK{2}, 'Color', C(2,:), ... %[output:9772e854]
    'MarkerSize', 5.0, 'LineWidth', 1.0); %[output:9772e854]

h6 = plot(ax1, xTheory(idxTh), MP_th(idxTh)/1e3, ... %[output:9772e854]
    'LineStyle', 'none', 'Marker', MK{3}, 'Color', C(3,:), ... %[output:9772e854]
    'MarkerSize', 5.0, 'LineWidth', 1.0); %[output:9772e854]

yline(ax1, 0, 'k:', 'HandleVisibility','off'); %[output:9772e854]
set(ax1, 'YDir', 'reverse'); %[output:9772e854]

xlabel(ax1, '$x$ (m)', 'Interpreter', 'latex'); %[output:9772e854]
ylabel(ax1, '$M_z$ (kN$\cdot$m)', 'Interpreter', 'latex'); %[output:9772e854]
title(ax1, '(a) Bending moment', 'FontWeight', 'normal'); %[output:9772e854]

% ========================================================================
% (b) Vertical displacement
% ========================================================================
ax2 = nexttile; %[output:9772e854]
hold(ax2,'on'); box(ax2,'on'); %[output:9772e854]

% FE curves
plot(ax2, case0.xNode, case0.uy*1e3, ... %[output:9772e854]
    'LineStyle', LS{1}, 'Color', C(1,:), 'LineWidth', LW(1), ... %[output:9772e854]
    'HandleVisibility','off'); %[output:9772e854]

plot(ax2, caseF.xNode, caseF.uy*1e3, ... %[output:9772e854]
    'LineStyle', LS{2}, 'Color', C(2,:), 'LineWidth', LW(2), ... %[output:9772e854]
    'HandleVisibility','off'); %[output:9772e854]

plot(ax2, caseP.xNode, caseP.uy*1e3, ... %[output:9772e854]
    'LineStyle', LS{3}, 'Color', C(3,:), 'LineWidth', LW(3), ... %[output:9772e854]
    'HandleVisibility','off'); %[output:9772e854]

% Theory markers
plot(ax2, xTheory(idxTh), u0_th(idxTh)*1e3, ... %[output:9772e854]
    'LineStyle', 'none', 'Marker', MK{1}, 'Color', C(1,:), ... %[output:9772e854]
    'MarkerSize', 5.0, 'LineWidth', 1.0, ... %[output:9772e854]
    'HandleVisibility','off'); %[output:9772e854]

plot(ax2, xTheory(idxTh), uF_th(idxTh)*1e3, ... %[output:9772e854]
    'LineStyle', 'none', 'Marker', MK{2}, 'Color', C(2,:), ... %[output:9772e854]
    'MarkerSize', 5.0, 'LineWidth', 1.0, ... %[output:9772e854]
    'HandleVisibility','off'); %[output:9772e854]

plot(ax2, xTheory(idxTh), uP_th(idxTh)*1e3, ... %[output:9772e854]
    'LineStyle', 'none', 'Marker', MK{3}, 'Color', C(3,:), ... %[output:9772e854]
    'MarkerSize', 5.0, 'LineWidth', 1.0, ... %[output:9772e854]
    'HandleVisibility','off'); %[output:9772e854]

yline(ax2, 0, 'k:', 'HandleVisibility','off'); %[output:9772e854]

xlabel(ax2, '$x$ (m)', 'Interpreter', 'latex'); %[output:9772e854]
ylabel(ax2, '$u_y$ (mm)', 'Interpreter', 'latex'); %[output:9772e854]
title(ax2, '(b) Vertical displacement', 'FontWeight', 'normal'); %[output:9772e854]

% ========================================================================
% Common axis style
% ========================================================================
set([ax1 ax2], ... %[output:9772e854]
    'FontName', 'Times New Roman', ... %[output:9772e854]
    'FontSize', 15, ... %[output:9772e854]
    'LineWidth', 1.0, ... %[output:9772e854]
    'TickDir', 'out', ... %[output:9772e854]
    'XMinorTick', 'on', ... %[output:9772e854]
    'YMinorTick', 'on', ... %[output:9772e854]
    'Layer', 'top'); %[output:9772e854]

xlim(ax1, [0 L]); %[output:9772e854]
xlim(ax2, [0 L]); %[output:9772e854]

% ========================================================================
% Legend
% Pair FE and theory entries for each case.
% ========================================================================
lgd = legend(ax2, [h1 h4 h2 h5 h3 h6], { ... %[output:9772e854]
    'Case 1 FE: $N=0$', ... %[output:9772e854]
    'Case 1 Theory', ... %[output:9772e854]
    'Case 2 FE: $N=qL/2$', ... %[output:9772e854]
    'Case 2 Theory', ... %[output:9772e854]
    'Case 3 FE: optimized', ... %[output:9772e854]
    'Case 3 Theory'}, ... %[output:9772e854]
    'Interpreter', 'latex', ... %[output:9772e854]
    'Location', 'southoutside', ... %[output:9772e854]
    'NumColumns', 3, ... %[output:9772e854]
    'Box', 'on', 'Color', 'white', ... %[output:9772e854]
    'EdgeColor', [0.35 0.35 0.35]); %[output:9772e854]

lgd.FontName = 'Times New Roman'; %[output:9772e854]
lgd.FontSize = 13; %[output:9772e854]

% ========================================================================
% Save figures
% ========================================================================
% exportgraphics(fig, fullfile(figDir,'prestressed_cable_demo.png'), 'Resolution', 600);
exportgraphics(fig, fullfile(figDir,'prestressed_cable_demo.pdf'), 'ContentType', 'vector'); %[output:9772e854]

figureData = [ ...
    makeFigureData("Bending moment", "FE", "Case 1", case0.xM, case0.M/1e3); ...
    makeFigureData("Bending moment", "FE", "Case 2", caseF.xM, caseF.M/1e3); ...
    makeFigureData("Bending moment", "FE", "Case 3", caseP.xM, caseP.M/1e3); ...
    makeFigureData("Bending moment", "Theory", "Case 1", xTheory, M0_th/1e3); ...
    makeFigureData("Bending moment", "Theory", "Case 2", xTheory, MF_th/1e3); ...
    makeFigureData("Bending moment", "Theory", "Case 3", xTheory, MP_th/1e3); ...
    makeFigureData("Vertical displacement", "FE", "Case 1", case0.xNode, case0.uy*1e3); ...
    makeFigureData("Vertical displacement", "FE", "Case 2", caseF.xNode, caseF.uy*1e3); ...
    makeFigureData("Vertical displacement", "FE", "Case 3", caseP.xNode, caseP.uy*1e3); ...
    makeFigureData("Vertical displacement", "Theory", "Case 1", xTheory, u0_th*1e3); ...
    makeFigureData("Vertical displacement", "Theory", "Case 2", xTheory, uF_th*1e3); ...
    makeFigureData("Vertical displacement", "Theory", "Case 3", xTheory, uP_th*1e3)];
writetable(figureData, fullfile(figDir, 'prestressed_cable_demo.csv'));
% savefig(fig, fullfile(figDir,'prestressed_cable_demo.fig'));
%%
%[text] ## Local functions
%[text] The functions below keep the main workflow short. They build the
%[text] OpenSeesMatlab model, evaluate the objective function, and generate the
%[text] closed-form reference curves used for verification.
%%
function data = makeFigureData(quantity, source, caseName, x, value)
    x = x(:);
    value = value(:);
    data = table( ...
        repmat(string(quantity), numel(x), 1), ...
        repmat(string(source), numel(x), 1), ...
        repmat(string(caseName), numel(x), 1), ...
        x, value, ...
        'VariableNames', {'Quantity','Source','Case','X_m','Value'});
end

function out = runModel(eps0, Nmid, L, q, E, A, Iz, Ec, Ac, hc, nEle)
% runModel
% -------------------------------------------------------------------------
% Build and analyze a simply supported beam with a vertical prestressed
% truss cable at midspan.
%
% Input arguments
% ---------------
% eps0 : initial strain assigned to the cable
% Nmid : additional upward nodal force applied at the beam midspan
% L    : beam span
% q    : uniformly distributed downward load
% E    : Young's modulus of the beam
% A    : cross-sectional area of the beam
% Iz   : second moment of area of the beam
% Ec   : Young's modulus of the cable
% Ac   : cross-sectional area of the cable
% hc   : vertical distance from beam midspan to anchor node
% nEle : number of beam elements
%
% Output
% ------
% out is a structure containing:
%   out.xNode  : beam node x-coordinates
%   out.uy     : vertical displacement of beam nodes
%   out.xM     : x-coordinates of bending moment points
%   out.M      : bending moment values
%   out.J      : objective value, integral of M^2 dx
%   out.Ncable : axial force in the cable
% -------------------------------------------------------------------------

    % Create a new OpenSeesMatlab instance.
    opsMAT = OpenSeesMatlab();
    ops = opsMAT.opensees;

    % Clear previous model and define a 2D frame model.
    % Each node has 3 DOFs: ux, uy, and rotation rz.
    ops.wipe();
    ops.model('basic','-ndm',2,'-ndf',3);

    % Basic mesh information.
    dx = L/nEle;
    midNode = nEle/2 + 1;
    anchorNode = nEle + 2;

    % ---------------------------------------------------------------------
    % Create beam nodes along the x-axis.
    % Node tags are 1, 2, ..., nEle+1.
    % ---------------------------------------------------------------------
    for i = 0:nEle
        ops.node(i+1, i*dx, 0.0);
    end

    % Create the fixed anchor node above the beam midspan.
    ops.node(anchorNode, L/2, hc);

    % ---------------------------------------------------------------------
    % Boundary conditions.
    %
    % Left support:
    %   ux = 0, uy = 0, rz free
    %
    % Right support:
    %   ux free, uy = 0, rz free
    %
    % Anchor node:
    %   fully fixed
    % ---------------------------------------------------------------------
    ops.fix(1,      1, 1, 0);
    ops.fix(nEle+1, 0, 1, 0);
    ops.fix(anchorNode, 1, 1, 1);

    % ---------------------------------------------------------------------
    % Beam elements.
    % The beam is modeled using elasticBeamColumn elements.
    % ---------------------------------------------------------------------
    ops.geomTransf('Linear',1);

    for e = 1:nEle
        ops.element('elasticBeamColumn', e, e, e+1, A, E, Iz, 1);
    end

    % ---------------------------------------------------------------------
    % Cable element.
    %
    % The cable is modeled by a truss element.
    % The InitStrainMaterial is used to introduce prestress through eps0.
    % ---------------------------------------------------------------------
    ops.uniaxialMaterial('Elastic', 1, Ec);
    ops.uniaxialMaterial('InitStrainMaterial', 2, 1, eps0);
    ops.element('truss', nEle+1, midNode, anchorNode, Ac, 2);

    % ---------------------------------------------------------------------
    % Apply external loads.
    %
    % 1. Uniform downward load q on all beam elements.
    % 2. Optional upward nodal force Nmid at midspan.
    % ---------------------------------------------------------------------
    ops.timeSeries('Linear',1);
    ops.pattern('Plain',1,1);

    eleTags = num2cell(1:nEle);
    ops.eleLoad('-ele', eleTags{:}, '-type', '-beamUniform', -q);

    if abs(Nmid) > 0
        ops.load(midNode, 0.0, Nmid, 0.0);
    end

    % ---------------------------------------------------------------------
    % Static analysis settings.
    % Since this is a linear elastic example, the Linear algorithm is enough.
    % ---------------------------------------------------------------------
    ops.constraints('Transformation');
    ops.numberer('RCM');
    ops.system('BandGeneral');
    ops.test('NormDispIncr',1e-10,20,0);
    ops.algorithm('Linear');
    ops.integrator('LoadControl',1.0);
    ops.analysis('Static');

    ok = ops.analyze(1);

    if ok ~= 0
        error('Analysis failed.');
    end

    % ---------------------------------------------------------------------
    % Extract vertical displacement of beam nodes.
    % ---------------------------------------------------------------------
    xNode = linspace(0,L,nEle+1).';
    uy = zeros(nEle+1,1);

    for i = 1:nEle+1
        uy(i) = ops.nodeDisp(i,2);
    end

    % ---------------------------------------------------------------------
    % Extract bending moment from beam-element basic forces.
    %
    % For a 2D elasticBeamColumn element, basicForce is usually:
    %
    %   [N, M_i, M_j]
    %
    % The bending moment convention used here is:
    %
    %   M_left  = -M_i
    %   M_right =  M_j
    %
    % Therefore, each beam element contributes two moment points.
    % ---------------------------------------------------------------------
    xM = zeros(2*nEle,1);
    M  = zeros(2*nEle,1);

    for e = 1:nEle
        bf = ops.eleResponse(e,'basicForce');
        bf = bf(:);

        xM(2*e-1) = (e-1)*dx;
        xM(2*e)   = e*dx;

        M(2*e-1) = -bf(2);
        M(2*e)   =  bf(3);
    end

    % ---------------------------------------------------------------------
    % Compute the objective function:
    %
    %   J = integral_0^L M^2(x) dx
    %
    % Within each element, M(x) is assumed to vary linearly between the two
    % element-end moments M1 and M2. Therefore:
    %
    %   integral M^2 dx = Le/3 * (M1^2 + M1*M2 + M2^2)
    % ---------------------------------------------------------------------
    J = 0.0;

    for e = 1:nEle
        M1 = M(2*e-1);
        M2 = M(2*e);

        J = J + dx/3*(M1^2 + M1*M2 + M2^2);
    end

    % ---------------------------------------------------------------------
    % Extract cable axial force.
    % For a truss element, the first basic force component is the axial force.
    % abs() is used because we are mainly interested in the force magnitude.
    % ---------------------------------------------------------------------
    bfCable = ops.eleResponse(nEle+1,'basicForce');
    Ncable = abs(bfCable(1));

    % Store useful results in a compact output structure.
    out.xNode  = xNode;
    out.uy     = uy;
    out.xM     = xM;
    out.M      = M;
    out.J      = J;
    out.Ncable = Ncable;

    % Clear OpenSees model after extracting all results.
    ops.wipe();
end

function M = momentTheory(N, x, L, q)
% momentTheory
% -------------------------------------------------------------------------
% Closed-form bending moment of a simply supported beam under:
%
%   1. uniform downward load q;
%   2. upward concentrated force N at midspan.
%
% Sign convention
% ---------------
% The returned moment follows the same engineering convention used in the
% finite-element post-processing.
% -------------------------------------------------------------------------

    % Support reaction due to q and N.
    R = (q*L - N)/2;

    % Moment caused by the left reaction and the uniform load.
    M = R.*x - 0.5*q.*x.^2;

    % For the right half of the beam, add the contribution of the upward
    % midspan force N.
    idx = x > L/2;
    M(idx) = M(idx) + N.*(x(idx) - L/2);
end

function uy = dispTheory(N, x, L, q, E, Iz)
% dispTheory
% -------------------------------------------------------------------------
% Closed-form vertical displacement of a simply supported Euler-Bernoulli
% beam under:
%
%   1. uniform downward load q;
%   2. upward concentrated force N at midspan.
%
% Sign convention
% ---------------
% Positive uy means upward displacement.
% Negative uy means downward displacement.
% -------------------------------------------------------------------------

    x = x(:);

    % ---------------------------------------------------------------------
    % Displacement caused by the uniform downward load q.
    %
    % The classical formula gives downward deflection as positive.
    % Here we use positive uy as upward, so a minus sign is added.
    % ---------------------------------------------------------------------
    uyQ = -q.*x.*(L^3 - 2*L*x.^2 + x.^3)/(24*E*Iz);

    % ---------------------------------------------------------------------
    % Displacement caused by the upward midspan force N.
    %
    % The formula is symmetric about midspan, so the left and right halves
    % are evaluated separately.
    % ---------------------------------------------------------------------
    uyN = zeros(size(x));

    idxL = x <= L/2;
    idxR = x >  L/2;

    xL = x(idxL);
    aR = L - x(idxR);

    uyN(idxL) = N.*xL.*(3*L^2 - 4*xL.^2)/(48*E*Iz);
    uyN(idxR) = N.*aR.*(3*L^2 - 4*aR.^2)/(48*E*Iz);

    % Total vertical displacement.
    uy = uyQ + uyN;
end


